// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.array;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.common.iteration.CloseableIteration;
import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.eclipse.rdf4j.model.impl.BooleanLiteral;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.ARRAYF;
import org.eclipse.rdf4j.model.vocabulary.STRF;
import org.eclipse.rdf4j.model.vocabulary.TEXTF;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.eclipse.rdf4j.query.algebra.evaluation.function.FunctionRegistry;
import org.eclipse.rdf4j.query.algebra.evaluation.function.TupleFunction;
import org.eclipse.rdf4j.query.algebra.evaluation.function.TupleFunctionRegistry;
import org.eclipse.rdf4j.query.algebra.evaluation.function.tuple.GenerateSeriesTupleFunction;
import org.eclipse.rdf4j.query.algebra.evaluation.function.tuple.SplitTupleFunction;
import org.eclipse.rdf4j.query.algebra.evaluation.function.tuple.UnnestTupleFunction;
import org.eclipse.rdf4j.query.algebra.evaluation.function.tuple.UnnestWithOrdinalityTupleFunction;
import org.junit.jupiter.api.Test;

class ArrayAndTupleFunctionsTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private static Literal json(String s) {
		return VF.createLiteral(s, CoreDatatype.RDF.JSON);
	}

	private static Literal integer(long v) {
		return VF.createLiteral(BigInteger.valueOf(v));
	}

	private static List<List<? extends Value>> rows(TupleFunction function, Value... args) {
		List<List<? extends Value>> rows = new ArrayList<>();
		try (CloseableIteration<? extends List<? extends Value>> iteration = function.evaluate(VF, args)) {
			while (iteration.hasNext()) {
				rows.add(iteration.next());
			}
		}
		return rows;
	}

	@Test
	void arrayContainsAndLength() {
		Literal array = json("[1, 2.0, \"x\", {\"@id\":\"urn:a\"}, true]");
		assertThat(new ArrayContains().evaluate(VF, array, integer(2))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ArrayContains().evaluate(VF, array, VF.createLiteral("x"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ArrayContains().evaluate(VF, array, VF.createIRI("urn:a"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ArrayContains().evaluate(VF, array, VF.createLiteral(true))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ArrayContains().evaluate(VF, array, integer(3))).isEqualTo(BooleanLiteral.FALSE);
		assertThat(new ArrayLength().evaluate(VF, array)).isEqualTo(integer(5));
		assertThatThrownBy(() -> new ArrayContains().evaluate(VF, json("{}"), integer(1)))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void generateSeries() {
		assertThat(new GenerateSeries().evaluate(VF, integer(1), integer(4))).isEqualTo(json("[1,2,3,4]"));
		assertThat(new GenerateSeries().evaluate(VF, integer(5), integer(1), integer(-2))).isEqualTo(json("[5,3,1]"));
		assertThat(new GenerateSeries().evaluate(VF, integer(1), integer(0))).isEqualTo(json("[]"));
		assertThat(new GenerateSeries().evaluate(VF, VF.createLiteral(new java.math.BigDecimal("0.5")), integer(2),
				VF.createLiteral(new java.math.BigDecimal("0.5")))).isEqualTo(json("[0.5,1.0,1.5,2.0]"));
		assertThat(new GenerateSeries().evaluate(VF, VF.createLiteral("2024-01-30", CoreDatatype.XSD.DATE),
				VF.createLiteral("2024-02-01", CoreDatatype.XSD.DATE)))
						.isEqualTo(
								json("[{\"@value\":\"2024-01-30\",\"@type\":\"http://www.w3.org/2001/XMLSchema#date\"},"
										+ "{\"@value\":\"2024-01-31\",\"@type\":\"http://www.w3.org/2001/XMLSchema#date\"},"
										+ "{\"@value\":\"2024-02-01\",\"@type\":\"http://www.w3.org/2001/XMLSchema#date\"}]"));
		assertThatThrownBy(() -> new GenerateSeries().evaluate(VF, integer(1), integer(2), integer(0)))
				.isInstanceOf(ValueExprEvaluationException.class);
		List<List<? extends Value>> rows = rows(new GenerateSeriesTupleFunction(), integer(1), integer(3));
		assertThat(rows).containsExactly(List.of(integer(1)), List.of(integer(2)), List.of(integer(3)));
	}

	@Test
	void unnestAndSplitTupleFunctions() {
		assertThat(rows(new UnnestTupleFunction(), json("[1,\"a\",null,{\"@id\":\"urn:x\"},[2]]"))).containsExactly(
				List.of(integer(1)), List.of(VF.createLiteral("a")), List.of(VF.createIRI("urn:x")),
				List.of(json("[2]")));
		assertThat(rows(new UnnestTupleFunction(), json("{\"k\":1,\"m\":\"v\"}"))).containsExactly(
				List.of(VF.createLiteral("k"), integer(1)), List.of(VF.createLiteral("m"), VF.createLiteral("v")));
		assertThat(rows(new UnnestWithOrdinalityTupleFunction(), json("[\"a\",\"b\"]"))).containsExactly(
				List.of(VF.createLiteral("a"), integer(1)), List.of(VF.createLiteral("b"), integer(2)));
		assertThat(rows(new SplitTupleFunction(), VF.createLiteral("a,b"), VF.createLiteral(",")))
				.containsExactly(List.of(VF.createLiteral("a")), List.of(VF.createLiteral("b")));
		assertThat(rows(new SplitTupleFunction(), null, VF.createLiteral(","))).isEmpty();
		assertThatThrownBy(() -> new UnnestTupleFunction().evaluate(VF, new Value[] { json("1") }).hasNext())
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void allRegistered() {
		TupleFunctionRegistry registry = TupleFunctionRegistry.getInstance();
		for (String iri : new String[] { ARRAYF.NAMESPACE + "unnest", ARRAYF.NAMESPACE + "unnestWithOrdinality",
				ARRAYF.NAMESPACE + "generateSeries", STRF.NAMESPACE + "split", STRF.NAMESPACE + "regexpExtractAll",
				TEXTF.NAMESPACE + "tokenize", TEXTF.NAMESPACE + "ngrams" }) {
			assertThat(registry.get(iri)).as(iri).isPresent();
		}
		for (String name : new String[] { "arrayContains", "arrayLength", "generateSeries" }) {
			assertThat(FunctionRegistry.getInstance().get(ARRAYF.NAMESPACE + name)).as(name).isPresent();
		}
	}
}
